-- BORRADOR: configuración SOLO local desechable y revisión de la temporada.
-- No ejecutarlo contra Supabase alojado. No abre ninguna ventana.
-- psql -X -v ON_ERROR_STOP=1 -v season_id=<UUID LOCAL> -f este_archivo.sql
-- Las reglas no se publican junto con la migración de funciones.
begin;
create temporary table _ml_clause_seed(start_cents bigint,end_cents bigint,multiplier numeric) on commit drop;
select set_config('macroliga.clause_seed_season', :'season_id',true);
do $$
declare
 v_season uuid:=current_setting('macroliga.clause_seed_season')::uuid;
begin
 if not exists(select 1 from public.seasons where id=v_season) then
   raise exception 'Temporada local inexistente';
 end if;
 perform 1 from public.divisions where season_id=v_season order by id for update;
 if exists(select 1 from public.clause_rules where season_id=v_season) then
   raise exception 'Temporada con reglas existentes: revisar versionado; no sobrescribir';
 end if;
   select v_season,start_cents,end_cents,multiplier,'MACROLIGA tabla original/extension aprobada - 2026-11-27',1
   from pg_temp._ml_clause_seed order by start_cents;
end $$;
commit;
